#!/usr/bin/env bash
set -euo pipefail
# shellcheck source=prereqs.sh
source "$(dirname "${BASH_SOURCE[0]}")/prereqs.sh"

SECRETS=(
  dalia20_secret_key
  dalia20_email_fernet_key
)

# Secrets that CANNOT be autogenerated — they must come from an external service dashboard.
# Any secret NOT in this list will show a g=generate option.
EXTERNAL_SECRETS=(
)

# Per-secret descriptions shown to the user during setup
declare -A SECRET_DESC=(
  [dalia20_secret_key]="Django SECRET_KEY — signs sessions, password-reset links, messages and API JWT tokens. Use g=generate (hex, 64 chars; Django needs >= 50). Changing it logs everyone out"
  [dalia20_email_fernet_key]="Encryption key for email-provider credentials stored in the admin panel. Use g=generate (hex, 256-bit). Replacing it means re-entering email passwords/API keys in the admin"
)

# Secrets that may be set to the placeholder value "unused" so the container starts
# even when the associated service is not yet active or configured.
# Use this for any secret whose container must exist in the Podman store — placeholder
# satisfies the mount requirement without providing a real credential.
PLACEHOLDER_SECRETS=(
)

# Secrets where leaving them ABSENT is itself a meaningful safety guard — their absence
# enforces a hard constraint (e.g. prevents an accidental dual-tunnel conflict on a server
# where that tunnel must NOT run). Only use this when absence will NOT cause a container
# startup failure and the deliberate absence IS the desired outcome.
SKIP_OK_SECRETS=(
)

# ─── Prereq check ─────────────────────────────────────────────────────────────

ensure_podman

# ─── Helpers ──────────────────────────────────────────────────────────────────

secret_exists() {
  podman secret inspect "$1" > /dev/null 2>&1
}

create_secret() {
  local name="$1"
  local value="${2%$'\n'}"
  printf '%s' "$value" | podman secret create "$name" - > /dev/null
}

# ─── Key format generators ────────────────────────────────────────────────────
# Each function outputs the generated value to stdout with no trailing newline.
# Command substitution $() in callers strips the single trailing newline from openssl.

_gen_hex() {
  # 256-bit — NIST SP 800-57 highest tier; universal, no special chars
  openssl rand -hex 32
}

_gen_base64() {
  # 256-bit — compact; contains +/= which break URLs and DSNs
  openssl rand -base64 32 | tr -d '\n'
}

_gen_base64_urlsafe() {
  # 256-bit — URL/cookie/header-safe; OWASP-recommended for embedded tokens
  openssl rand -base64 32 | tr '+/' '-_' | tr -d '=\n'
}

_gen_alphanumeric() {
  # ~190-bit — DSN-safe, human-copyable; bash substring avoids SIGPIPE from head -c
  local _raw
  _raw=$(openssl rand -base64 48 | tr -dc 'A-Za-z0-9')
  printf '%s' "${_raw:0:32}"
}

_gen_sk_prefix() {
  # 256-bit hex with sk- prefix — required by LiteLLM; OpenAI-compatible key pattern
  printf 'sk-%s' "$(openssl rand -hex 32)"
}

# Interactive: show format menu, read choice with </dev/tty (safe under make), echo format number.
# Called in the main shell flow BEFORE generate_secret_for so no command-substitution subshell.
prompt_secret_format() {
  local name="$1"
  local default_fmt
  case "$name" in
    dalia20_secret_key|dalia20_email_fernet_key) default_fmt=1 ;;  # Hex
    *)                                      default_fmt=1 ;;  # Hex
  esac

  printf '\n     Key format:\n' >&2
  printf '       [1] Hex            — 256-bit, 64 hex chars,  universal\n' >&2
  printf '       [2] Base64         — 256-bit, ~44 chars,     contains +/= (avoid in URLs/DSNs)\n' >&2
  printf '       [3] Base64-URL     — 256-bit, ~43 chars,     URL/cookie/header-safe\n' >&2
  printf '       [4] Alphanumeric   — ~190-bit, 32 chars,     DSN-safe, human-copyable\n' >&2
  printf '       [5] sk- prefix     — 256-bit, sk-<hex>,      LiteLLM/OpenAI-compatible\n' >&2
  printf '     Choice [%s]: ' "$default_fmt" >&2
  local choice
  read -r choice </dev/tty
  [ -z "$choice" ] && choice="$default_fmt"

  case "$choice" in
    1|2|3|4|5) printf '%s' "$choice" ;;
    *) printf '\n     [WARN] Invalid choice — using Hex\n' >&2; printf '1' ;;
  esac
}

# Pure compute: generate a secret value in the given format. No user interaction.
# fmt: 1=hex 2=base64 3=base64-urlsafe 4=alphanumeric 5=sk-prefix
generate_secret_for() {
  local name="$1"
  local fmt="${2:-1}"
  ensure_openssl
  case "$fmt" in
    1) _gen_hex ;;
    2) _gen_base64 ;;
    3) _gen_base64_urlsafe ;;
    4) _gen_alphanumeric ;;
    5) _gen_sk_prefix ;;
    *) _gen_hex ;;
  esac
}

# Returns 0 if the secret can be set to a placeholder when the service is not in use
is_placeholder_ok() {
  local name="$1"
  for s in "${PLACEHOLDER_SECRETS[@]}"; do
    [ "$s" = "$name" ] && return 0
  done
  return 1
}

# Returns 0 if leaving the secret absent is an intentional safe choice (container won't start — that's the goal)
is_skip_ok() {
  local name="$1"
  for s in "${SKIP_OK_SECRETS[@]}"; do
    [ "$s" = "$name" ] && return 0
  done
  return 1
}

# Returns 0 if the secret must come from an external service (no autogenerate)
is_external() {
  local name="$1"
  for s in "${EXTERNAL_SECRETS[@]}"; do
    [ "$s" = "$name" ] && return 0
  done
  return 1
}

# ─── Subcommands ──────────────────────────────────────────────────────────────

cmd_setup() {
  local R='\033[0m'        # reset
  local BOLD='\033[1m'
  local CYAN='\033[1;36m'    # header, secret name
  local YEL='\033[0;33m'    # description
  local GRN='\033[1;32m'    # [OK], rotated/created results
  local RED='\033[1;31m'    # [SKIPPED], error results
  local WHT='\033[1;37m'    # options/action line
  local DIM='\033[2m'       # secondary info
  local BGGRN='\033[42m'       # green background — status [exists]
  local BGRED='\033[41m'       # red background   — status [missing]
  local BLU='\033[1;34m'       # skipped count
  local ORG='\033[38;5;208m'   # generated count (orange)
  local YELBRT='\033[1;33m'    # placeholder count (bright yellow)

  printf "${CYAN}"
  echo ""
  echo "╔══════════════════════════════════════════════════════════════╗"
  echo "║                     Podman Secrets Setup                     ║"
  echo "╠══════════════════════════════════════════════════════════════╣"
  printf "${R}${BOLD}"
  echo "║  Existing secret options:                                    ║"
  printf "${R}"
  echo "║    Enter  keep current value                                 ║"
  echo "║    e      replace with a new value                           ║"
  echo "║    g      regenerate — prompts for key format (hex,          ║"
  echo "║           base64, base64-url-safe, alphanumeric, sk-prefix)  ║"
  echo "║    p      set to placeholder 'unused'  (optional only)       ║"
  echo "║    d      delete                                             ║"
  echo "║                                                              ║"
  printf "${BOLD}"
  echo "║  Missing secret options:                                     ║"
  printf "${R}"
  echo "║    <value>  enter real value (hidden input)                  ║"
  echo "║    g        generate — prompts for key format                ║"
  echo "║    p        set to placeholder 'unused'  (optional only)     ║"
  echo "║    s        skip — leave absent  (skip-ok secrets only)      ║"
  echo "║                                                              ║"
  printf "${RED}"
  echo "║  Skipping a missing secret leaves it absent — the container  ║"
  echo "║  that mounts it will NOT start until a value is set.         ║"
  printf "${CYAN}"
  echo "╚══════════════════════════════════════════════════════════════╝"
  printf "${R}\n"

  local created=0 updated=0 generated=0 placeholder=0 kept=0 deleted=0 skipped=0 name action val opts can_gen can_placeholder can_skip desc

  # .env file paths (used for CLOUDFLARE_ZONE_ID prompt inside the loop)
  local env_file env_example_file curdir
  env_file="$(dirname "${BASH_SOURCE[0]}")/../.env"
  env_file="$(realpath "$env_file")"
  env_example_file="$(dirname "${BASH_SOURCE[0]}")/../.env.example"
  env_example_file="$(realpath "$env_example_file")"

  # Ensure .env exists before we might need to write CLOUDFLARE_ZONE_ID
  if [ ! -f "$env_file" ]; then
    cp "$env_example_file" "$env_file"
    curdir="$(dirname "$env_file")"
    sed -i "s|PROJECT_ROOT=.*|PROJECT_ROOT=$curdir|" "$env_file"
    printf "  ${GRN}→ Created .env from .env.example${R}\n\n"
  fi

  _read_env_key() {
    local key="$1"
    grep -E "^${key}=" "$env_file" 2>/dev/null | tail -1 | cut -d= -f2- || echo ""
  }

  _write_env_key() {
    local key="$1" value="$2"
    if grep -qE "^${key}=" "$env_file" 2>/dev/null; then
      sed -i "s|^${key}=.*|${key}=${value}|" "$env_file"
    else
      echo "${key}=${value}" >> "$env_file"
    fi
  }

  for name in "${SECRETS[@]}"; do
    # .env config value: prompt for CLOUDFLARE_ZONE_ID before the API token
    if [ "$name" = "dalia20_cloudflare_api_token" ]; then
      printf "  ${CYAN}"
      echo "┌──────────────────────────────────────────────────────────────┐"
      echo "│  .env Config Value (not a Podman secret)                     │"
      echo "└──────────────────────────────────────────────────────────────┘"
      printf "${R}"
      local cf_zone_current cf_zone_new
      cf_zone_current="$(_read_env_key CLOUDFLARE_ZONE_ID)"
      printf "  ${CYAN}── CLOUDFLARE_ZONE_ID${R}\n"
      printf "     ${YEL}32-char hex Zone ID from Cloudflare dashboard → your domain → Zone ID.\n"
      printf "     Required by cloudflare-analytics.sh to pull daily traffic stats.\n"
      printf "     Optional — analytics will be skipped (exit 0) if not set.${R}\n"
      if [ -n "$cf_zone_current" ] && printf '%s' "$cf_zone_current" | grep -qE '^[a-f0-9]{32}$'; then
        printf "     Status : ${BGGRN}${BOLD} [set] ${R}  ${DIM}%.8s...${R}\n" "$cf_zone_current"
        printf "     ${WHT}Action : Enter new value  ${DIM}[Enter = keep]${R} → "
        read -r cf_zone_new </dev/tty
        if [ -n "$cf_zone_new" ]; then
          if printf '%s' "$cf_zone_new" | grep -qE '^[a-f0-9]{32}$'; then
            _write_env_key CLOUDFLARE_ZONE_ID "$cf_zone_new"
            printf "     ${GRN}→ [OK] updated${R}\n"
          else
            printf "     ${RED}→ [KEPT] invalid format (must be 32 lowercase hex chars) — keeping existing value${R}\n"
          fi
        else
          printf "     ${DIM}→ [KEEP]${R}\n"
        fi
      else
        if [ -n "$cf_zone_current" ]; then
          printf "     Status : ${BGRED}${BOLD} [invalid placeholder] ${R}\n"
        else
          printf "     Status : ${BGRED}${BOLD} [not set] ${R}\n"
        fi
        printf "     ${WHT}Enter Zone ID / s=skip (hidden):${R} "
        read -r -s cf_zone_new </dev/tty
        echo ""
        case "$cf_zone_new" in
          s|S|"")
            printf "     ${DIM}→ [SKIPPED] analytics will be skipped until CLOUDFLARE_ZONE_ID is set in .env${R}\n"
            ;;
          *)
            if printf '%s' "$cf_zone_new" | grep -qE '^[a-f0-9]{32}$'; then
              _write_env_key CLOUDFLARE_ZONE_ID "$cf_zone_new"
              printf "     ${GRN}→ [OK] written to .env${R}\n"
            else
              printf "     ${RED}→ [SKIPPED] invalid format (must be 32 lowercase hex chars) — not written${R}\n"
            fi
            ;;
        esac
      fi
      echo ""
    fi

    is_external "$name" && can_gen="n" || can_gen="y"
    is_placeholder_ok "$name" && can_placeholder="y" || can_placeholder="n"
    is_skip_ok "$name" && can_skip="y" || can_skip="n"
    desc="${SECRET_DESC[$name]:-}"

    printf "  ${CYAN}── %s${R}\n" "$name"

    if secret_exists "$name"; then
      printf "     Status : ${BGGRN}${BOLD} [exists] ${R}\n"
      opts="e=edit"
      [ "$can_gen"         = "y" ] && opts="$opts / g=regen"
      [ "$can_placeholder" = "y" ] && opts="$opts / p=placeholder"
      opts="$opts / d=delete"
      printf "     ${WHT}Action : %s${R}  ${DIM}[Enter = keep]${R} → " "$opts"
      read -r action </dev/tty

      case "$action" in
        e|E)
          opts="value"
          [ "$can_gen"         = "y" ] && opts="$opts / g=generate"
          [ "$can_placeholder" = "y" ] && opts="$opts / p=placeholder"
          printf "     ${WHT}New value (%s, hidden):${R} " "$opts"
          read -r -s val </dev/tty
          echo ""
          if [ -z "$val" ]; then
            printf "     ${DIM}→ [KEEP] empty input — keeping existing value${R}\n"
            kept=$((kept + 1))
          else
            case "$val" in
              g|G)
                if [ "$can_gen" = "y" ]; then
                  local _fmt; _fmt=$(prompt_secret_format "$name")
                  val=$(generate_secret_for "$name" "$_fmt")
                  podman secret rm "$name" >/dev/null
                  create_secret "$name" "$val"
                  printf "     ${GRN}→ [OK] generated${R}\n"
                  generated=$((generated + 1))
                else
                  printf "     ${DIM}→ [KEEP] cannot autogenerate external secret${R}\n"
                  kept=$((kept + 1))
                fi
                ;;
              p|P)
                if [ "$can_placeholder" = "y" ]; then
                  podman secret rm "$name" >/dev/null
                  create_secret "$name" "unused"
                  printf "     ${GRN}→ [OK] set to placeholder 'unused'${R}\n"
                  placeholder=$((placeholder + 1))
                else
                  printf "     ${DIM}→ [KEEP] placeholder not allowed — this secret is required${R}\n"
                  kept=$((kept + 1))
                fi
                ;;
              *)
                podman secret rm "$name" >/dev/null
                create_secret "$name" "$val"
                printf "     ${GRN}→ [OK] updated${R}\n"
                updated=$((updated + 1))
                ;;
            esac
          fi
          ;;
        g|G)
          if [ "$can_gen" = "y" ]; then
            local _fmt; _fmt=$(prompt_secret_format "$name")
            val=$(generate_secret_for "$name" "$_fmt")
            podman secret rm "$name" >/dev/null
            create_secret "$name" "$val"
            printf "     ${GRN}→ [OK] generated${R}\n"
            generated=$((generated + 1))
          else
            printf "     ${DIM}→ [KEEP] cannot autogenerate external secret${R}\n"
            kept=$((kept + 1))
          fi
          ;;
        p|P)
          if [ "$can_placeholder" = "y" ]; then
            podman secret rm "$name" >/dev/null
            create_secret "$name" "unused"
            printf "     ${GRN}→ [OK] set to placeholder 'unused'${R}\n"
            placeholder=$((placeholder + 1))
          else
            printf "     ${DIM}→ [KEEP] placeholder not allowed — this secret is required${R}\n"
            kept=$((kept + 1))
          fi
          ;;
        d|D)
          podman secret rm "$name" >/dev/null
          printf "     ${GRN}→ [OK] deleted${R}\n"
          deleted=$((deleted + 1))
          ;;
        *)
          printf "     ${DIM}→ [KEEP]${R}\n"
          kept=$((kept + 1))
          ;;
      esac

    else
      printf "     Status : ${BGRED}${BOLD} [missing] ${R}\n"
      [ -n "$desc" ] && printf "     ${YEL}%s${R}\n" "$desc"
      local _prompt_opts="Enter value"
      [ "$can_gen"         = "y" ] && _prompt_opts="$_prompt_opts / g=generate"
      [ "$can_placeholder" = "y" ] && _prompt_opts="$_prompt_opts / p=placeholder"
      [ "$can_skip"        = "y" ] && _prompt_opts="$_prompt_opts / s=skip"
      if [ "$can_gen" = "n" ] && [ "$can_placeholder" = "n" ] && [ "$can_skip" = "n" ]; then
        printf "     ${RED}%s — REQUIRED (hidden):${R} " "$_prompt_opts"
      else
        printf "     ${WHT}%s (hidden):${R} " "$_prompt_opts"
      fi
      read -r -s val </dev/tty
      echo ""

      case "$val" in
        g|G)
          if [ "$can_gen" = "y" ]; then
            local _fmt; _fmt=$(prompt_secret_format "$name")
            val=$(generate_secret_for "$name" "$_fmt")
            create_secret "$name" "$val"
            printf "     ${GRN}→ [OK] generated${R}\n"
            generated=$((generated + 1))
          else
            printf "     ${RED}→ [SKIPPED] cannot autogenerate external secret — container will NOT start${R}\n"
            skipped=$((skipped + 1))
          fi
          ;;
        p|P)
          if [ "$can_placeholder" = "y" ]; then
            create_secret "$name" "unused"
            printf "     ${GRN}→ [OK] created (placeholder 'unused')${R}\n"
            placeholder=$((placeholder + 1))
          else
            printf "     ${RED}→ [SKIPPED] placeholder not allowed — container will NOT start${R}\n"
            skipped=$((skipped + 1))
          fi
          ;;
        s|S)
          if [ "$can_skip" = "y" ]; then
            printf "     ${DIM}→ [SKIPPED] left absent intentionally — container will not start${R}\n"
            skipped=$((skipped + 1))
          else
            printf "     ${RED}→ [ERROR] 's' (skip) is not valid for this secret — no value stored. Container will NOT start.${R}\n"
            skipped=$((skipped + 1))
          fi
          ;;
        "")
          printf "     ${RED}→ [SKIPPED] no value entered — container will NOT start${R}\n"
          skipped=$((skipped + 1))
          ;;
        *)
          create_secret "$name" "$val"
          printf "     ${GRN}→ [OK] created${R}\n"
          created=$((created + 1))
          ;;
      esac
    fi
    echo ""
  done

  printf "${CYAN}══════════════════════════════════════════════════════════════${R}\n"
  printf " Done.  ${DIM}Kept: $kept${R}  ${GRN}Created: $created${R}"
  [ "$updated"     -gt 0 ] && printf "  ${GRN}Updated: $updated${R}"
  [ "$generated"   -gt 0 ] && printf "  ${ORG}Generated: $generated${R}"
  [ "$placeholder" -gt 0 ] && printf "  ${YELBRT}Placeholder: $placeholder${R}"
  if [ "$deleted" -gt 0 ]; then
    printf "  ${RED}Deleted: $deleted${R}"
  else
    printf "  ${DIM}Deleted: $deleted${R}"
  fi
  printf "  ${BLU}Skipped: $skipped${R}\n"
  printf "${CYAN}══════════════════════════════════════════════════════════════${R}\n\n"
  printf "Run ${BOLD}bash scripts/secrets.sh list${R} to verify all secrets.\n\n"

}

cmd_list() {
  echo "[INFO] dalia20 Podman secrets:"
  echo ""
  local found=0 missing=0 name desc
  for name in "${SECRETS[@]}"; do
    desc="${SECRET_DESC[$name]:-}"
    if secret_exists "$name"; then
      local created_at
      created_at=$(podman secret inspect "$name" --format '{{.CreatedAt}}' 2>/dev/null || echo "unknown")
      if [ -n "$desc" ]; then
        printf "  [OK]      %-30s  created: %s  — %s\n" "$name" "$created_at" "$desc"
      else
        printf "  [OK]      %-30s  created: %s\n" "$name" "$created_at"
      fi
      found=$((found + 1))
    else
      if [ -n "$desc" ]; then
        printf "  [MISSING] %-30s                    — %s\n" "$name" "$desc"
      else
        printf "  [MISSING] %s\n" "$name"
      fi
      missing=$((missing + 1))
    fi
  done
  echo ""
  echo "[INFO] Found: $found  Missing: $missing"
  if [ "$missing" -gt 0 ]; then
    echo "[INFO] Run 'bash scripts/secrets.sh setup' to create missing secrets."
  fi
}

cmd_add() {
  local name="${1:-}"
  if [ -z "$name" ]; then
    echo "[ERROR] Usage: bash scripts/secrets.sh add <secret_name>" >&2
    exit 1
  fi
  if secret_exists "$name"; then
    echo "[WARN] $name already exists. Use 'edit' to rotate it."
    exit 0
  fi

  local can_gen
  is_external "$name" && can_gen="n" || can_gen="y"

  if [ "$can_gen" = "y" ]; then
    printf "Enter value for %s (hidden, or g=generate): " "$name"
  else
    printf "Enter value for %s (hidden): " "$name"
  fi
  local value
  read -r -s value
  echo ""

  if [ -z "$value" ]; then
    echo "[ERROR] No value provided — aborting." >&2
    exit 1
  fi

  case "$value" in
    g|G)
      if [ "$can_gen" = "y" ]; then
        local _fmt; _fmt=$(prompt_secret_format "$name")
        value=$(generate_secret_for "$name" "$_fmt")
        echo "[INFO] Generated random value"
      else
        echo "[ERROR] External secrets cannot be autogenerated." >&2
        exit 1
      fi
      ;;
  esac

  create_secret "$name" "$value"
  echo "[OK] $name — created"
}

cmd_edit() {
  local name="${1:-}"
  if [ -z "$name" ]; then
    echo "[ERROR] Usage: bash scripts/secrets.sh edit <secret_name>" >&2
    exit 1
  fi
  if ! secret_exists "$name"; then
    echo "[WARN] $name does not exist. Use 'add' to create it."
    exit 0
  fi

  local can_gen
  is_external "$name" && can_gen="n" || can_gen="y"

  if [ "$can_gen" = "y" ]; then
    printf "New value for %s (hidden, or g=generate): " "$name"
  else
    printf "New value for %s (hidden): " "$name"
  fi
  local value
  read -r -s value
  echo ""

  if [ -z "$value" ]; then
    echo "[ERROR] No value provided — aborting." >&2
    exit 1
  fi

  case "$value" in
    g|G)
      if [ "$can_gen" = "y" ]; then
        local _fmt; _fmt=$(prompt_secret_format "$name")
        value=$(generate_secret_for "$name" "$_fmt")
        echo "[INFO] Generated random value"
      else
        echo "[ERROR] External secrets cannot be autogenerated." >&2
        exit 1
      fi
      ;;
  esac

  # Podman does not support in-place secret editing — remove then recreate
  echo "[INFO] Removing old secret $name..."
  podman secret rm "$name" > /dev/null
  create_secret "$name" "$value"
  echo "[OK] $name — rotated"
}

cmd_remove() {
  local name="${1:-}"
  if [ -z "$name" ]; then
    echo "[ERROR] Usage: bash scripts/secrets.sh remove <secret_name>" >&2
    exit 1
  fi
  if ! secret_exists "$name"; then
    echo "[WARN] $name does not exist — nothing to remove."
    exit 0
  fi
  podman secret rm "$name" > /dev/null
  echo "[OK] $name — removed"
}

cmd_show() {
  local name="${1:-}"
  if [ -z "$name" ]; then
    echo "[ERROR] Usage: bash scripts/secrets.sh show <secret_name>" >&2
    exit 1
  fi
  if ! secret_exists "$name"; then
    echo "[ERROR] $name does not exist." >&2
    exit 1
  fi
  # Try --showsecret flag (Podman >= 4.4); fall back to guidance for older versions
  if podman secret inspect --showsecret "$name" --format '{{.SecretData}}' 2>/dev/null; then
    : # success
  else
    echo "[INFO] --showsecret not supported on this Podman version."
    echo "[INFO] To read the value inside a running container:"
    echo "         podman exec <container> cat /run/secrets/$name"
  fi
}

cmd_export() {
  printf '[WARN] Output contains plaintext secrets. Pipe directly via SSH or redirect to an encrypted file.\n' >&2
  printf '[WARN] Never commit or store this output in plain text.\n' >&2
  local name val exported=0 skipped=0
  for name in "${SECRETS[@]}"; do
    # Safety: only export secrets belonging to this project
    if [[ "$name" != dalia20_* ]]; then
      printf '[SKIP] %s — not a dalia20 secret, skipping\n' "$name" >&2
      continue
    fi
    if ! secret_exists "$name"; then
      printf '[SKIP] %s — not found on this server\n' "$name" >&2
      skipped=$((skipped + 1))
      continue
    fi
    val=$(podman secret inspect --showsecret "$name" --format '{{.SecretData}}' 2>/dev/null)
    printf '%s=%s\n' "$name" "$val"
    exported=$((exported + 1))
  done
  printf '[INFO] Exported: %d  Skipped: %d\n' "$exported" "$skipped" >&2
}

cmd_import() {
  local file="${1:-}"
  local input
  if [ -n "$file" ]; then
    if [ ! -f "$file" ]; then
      printf '[ERROR] File not found: %s\n' "$file" >&2
      exit 1
    fi
    input="$file"
  else
    input="/dev/stdin"
  fi

  local created=0 skipped=0 unknown=0 name val line
  while IFS= read -r line; do
    # skip blank lines and comments
    [[ "$line" =~ ^[[:space:]]*$ ]] && continue
    [[ "$line" =~ ^# ]] && continue

    name="${line%%=*}"
    val="${line#*=}"

    # check if it's a known secret
    local known=0
    for s in "${SECRETS[@]}"; do
      [ "$s" = "$name" ] && known=1 && break
    done
    if [ "$known" = "0" ]; then
      printf '[UNKNOWN] %s — not in managed secrets list, skipping\n' "$name" >&2
      unknown=$((unknown + 1))
      continue
    fi

    if secret_exists "$name"; then
      printf '[SKIP] %s — already exists (run: make secrets-edit NAME=%s to overwrite)\n' "$name" "$name"
      skipped=$((skipped + 1))
    else
      create_secret "$name" "$val"
      printf '[OK] %s — created\n' "$name"
      created=$((created + 1))
    fi
  done < "$input"

  printf '\n[INFO] Import complete. Created: %d  Skipped: %d  Unknown: %d\n' "$created" "$skipped" "$unknown"
  printf '[INFO] Run: bash scripts/secrets.sh list\n'
  printf '[INFO] Then: make up\n'
}

cmd_help() {
  cat <<'EOF'
Usage: bash scripts/secrets.sh <command> [args]

Commands:
  setup              Walk through all secrets interactively
                       Existing: e=edit (remove+create) / g=regen / d=delete / Enter=keep
                       Missing:  enter value / g=generate (non-external only) / p=placeholder / s=skip
  list               Show which secrets exist, their creation timestamps, and descriptions
  add <name>         Create a single secret; prompts for value (g=generate for non-external)
  edit <name>        Rotate a secret: removes old, prompts for new value (g=generate for non-external)
                     NOTE: Podman does not support in-place editing — edit = remove + create
  remove <name>      Remove a secret
  show <name>        Print secret value (requires Podman >= 4.4)
  export             Dump all secrets as KEY=VALUE to stdout (plaintext — pipe via SSH or encrypt before saving)
  import [FILE]      Create secrets from KEY=VALUE on stdin; or pass FILE=path via make
                     Skips secrets that already exist — safe to re-run on a partially-configured server

Managed secrets:
  dalia20_secret_key               — REQUIRED; autogenerate with g (hex, 64 chars; Django SECRET_KEY)
  dalia20_email_fernet_key         — REQUIRED; autogenerate with g (hex, 256-bit; encrypts email credentials)

Note: REQUIRED secrets must have real values — skipping them will cause container startup failures.
      Changing dalia20_secret_key logs everyone out; changing dalia20_email_fernet_key means
      re-entering email credentials in the admin.
EOF
}

# ─── Dispatch ─────────────────────────────────────────────────────────────────

cmd="${1:-help}"
shift || true

case "$cmd" in
  setup)   cmd_setup ;;
  list)    cmd_list ;;
  add)     cmd_add "${1:-}" ;;
  edit)    cmd_edit "${1:-}" ;;
  remove)  cmd_remove "${1:-}" ;;
  show)    cmd_show "${1:-}" ;;
  export)  cmd_export ;;
  import)  cmd_import "${1:-}" ;;
  help|--help|-h) cmd_help ;;
  *)
    echo "[ERROR] Unknown command: $cmd" >&2
    cmd_help
    exit 1
    ;;
esac
